import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            String nom = in.next();
            int h = in.nextInt();
            int blok = 4;
            while (blok < h) {
                blok *= 2;
            }
            System.out.println(nom + " " + blok + " /" + (32 - Integer.numberOfTrailingZeros(blok)));
        }
    }
}

