#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string nom;
        int h;
        cin >> nom >> h;
        int blok = 4;
        while (blok < h) {
            blok *= 2;
        }
        int p = 0;
        int t = blok;
        while (t > 1) {
            t /= 2;
            p += 1;
        }
        cout << nom << " " << blok << " /" << 32 - p << endl;
    }
    return 0;
}

